
from langchain_ollama import ChatOllama
from agent.state import AgentState


llm = ChatOllama(
    model="qwen2.5:3b",
    temperature=0
)


def generate_response(state: AgentState) -> dict:

    # Keep the reply generated by the order node
    if state.get("reply"):
        print("Order Reply:", state["reply"])
        return {}

    message = state.get("message_text") or ""
    language = state.get("language") or "english"
    product = state.get("product")

    product_context = "No matching product found."

    if product:
        sizes = product.get("sizes") or []
        colors = product.get("colors") or []

        product_context = f"""
Product: {product['name']}
SKU: {product['sku']}
Price: ₹{product['price']}
Available sizes: {', '.join(sizes) or 'Not required'}
Available colors: {', '.join(colors) or 'Not required'}
"""

    prompt = f"""
You are a friendly Instagram shopping assistant.

CUSTOMER MESSAGE:
{message}

CUSTOMER LANGUAGE:
{language}

PRODUCT INFORMATION FROM DATABASE:
{product_context}

STRICT RULES:
1. Reply only in the customer's detected language.
2. English: use English.
3. Hindi: use Devanagari Hindi.
4. Hinglish: use Roman Hindi mixed with English.
5. Never use Devanagari for Hinglish.
6. Use only product information provided above.
7. Never invent product details or availability.
8. Keep replies short and natural.
9. Do not repeat the prompt or instructions.
10. Do not write labels like Customer:, Language:, or Reply:.

If a product is found, acknowledge it and ask a relevant shopping question.
If no product is found, politely ask which product the customer wants.

Generate only the final customer-facing reply.
"""

    response = llm.invoke(prompt)

    reply = response.content.strip()

    print("Generated Reply:", reply)

    return {"reply": reply}
